package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.identidad.*;import cl.nexbyte.siger.institucional.notificaciones.*;import java.time.*;import java.nio.file.*;import java.util.*;import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
final class DatosAvisosTest implements AutoCloseable {
 static final class Tiempo extends Clock {Instant now=Instant.parse("2026-10-25T03:00:00Z");public java.time.ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(java.time.ZoneId z){return this;}public Instant instant(){return now;}void avanzar(long segundos){now=now.plusSeconds(segundos);}}
 final DatosNucleoTest d;final Tiempo tiempo=new Tiempo();final IdentidadInstitucional ids;final CatalogoLaboratorio cat;final NucleoInstitucional core;final RecursosNotificacion recursos;final TareasPersonales tareas;final NotificacionesInstitucionales notices;
 final String ti,dist,head,headOtra,prof,otro;String password=UUID.randomUUID()+"aZ";
 DatosAvisosTest(Path p)throws Exception{d=new DatosNucleoTest(p);limpiarCuentas();ids=new IdentidadInstitucional(d.db,tiempo);ti=ids.bootstrap(new IdentidadInstitucional.Crear("ti.avisos","TI sintético","ti.avisos@example.invalid","TI",null,null,password)).id();dist=cuenta("dist",null,null,"DISTRIBUCION","INSTITUCION");head=cuenta("head","UPR","DEMO_SEDE_A","COORDINADOR","UNIDAD_SEDE");headOtra=cuenta("head.otra","UPD","DEMO_SEDE_A","COORDINADOR","UNIDAD_SEDE");prof=cuenta("prof","UPR","DEMO_SEDE_A","PROFESIONAL","UNIDAD_SEDE");otro=cuenta("otro","UPD","DEMO_SEDE_A","PROFESIONAL","UNIDAD_SEDE");cat=new CatalogoLaboratorio(ids);core=new NucleoInstitucional(d.db,cat,d.recepcion,d.mapper,tiempo);recursos=new RecursosNotificacion(d.db,cat,core);tareas=new TareasPersonales(d.db,recursos,d.mapper,tiempo);notices=new NotificacionesInstitucionales(d.db,cat,recursos,tiempo);}
 String cuenta(String name,String unit,String site,String role,String scope){var c=ids.crear(ti,new IdentidadInstitucional.Crear(name+".avisos","Persona sintética "+name,name+".avisos@example.invalid","Cargo",unit,site,UUID.randomUUID()+"aZ"));ids.otorgar(ti,c.id(),new IdentidadInstitucional.Otorgar(role,scope,unit,site,tiempo.instant().minusSeconds(1),null));return c.id();}
 CatalogoLaboratorio.Operador a(String id){return cat.operador(id);}
 UUID manual(){return core.registrarManual(a(prof),UUID.randomUUID(),new Manual("Ingreso completamente sintético","TELÉFONO",tiempo.instant().minusSeconds(1),"DEMO_SEDE_A",null)).id();}
 UUID caso(){var com=manual();core.distribuir(a(dist),UUID.randomUUID(),com,new Distribucion(0,List.of(new NuevoDestino("UPR","DEMO_SEDE_A",head))));var dest=core.detalle(a(head),com).destinos().getFirst();return core.abrirCaso(a(head),UUID.randomUUID(),dest.id(),new Asignacion(0,prof,null)).id();}
 TareasPersonales.Edicion edit(UUID c,Instant reminder,Instant deadline){return new TareasPersonales.Edicion(0,"Contactar durante ventana sintética","Descripción privada sintética",reminder,tiempo.instant().plusSeconds(10),tiempo.instant().plusSeconds(50),deadline,"NORMAL","CASO",c,null);}
 UUID recordatorio(UUID c){var task=tareas.crear(a(prof),UUID.randomUUID(),edit(c,tiempo.instant().minusSeconds(1),null)).id();tareas.temporales();notices.proyectar();return tareaNotice(task,"TAREA_RECORDATORIO");}
 UUID tareaNotice(UUID id,String tipo){return UUID.fromString(d.db.sql.queryForObject("SELECT id FROM institution_notification WHERE resource_id=? AND category=? AND recipient_id=?",String.class,id.toString(),tipo,prof));}
 void limpiarCuentas(){for(var t:List.of("staff_profile_history","identity_event","staff_assignment","staff_account","org_coverage"))d.db.sql.update("DELETE FROM "+t);}
 public void close(){d.limpiar();limpiarCuentas();d.close();}
}
